{"path": "test-server.js", "content": "const http = require('http');
const fs = require('fs');
const path = require('path');

console.log('🧪 开始贪吃蛇游戏项目测试...\n');

let testsPassed = 0;
let testsFailed = 0;

function test(name, testFunction) {
  try {
    testFunction();
    console.log(`✅ ${name}`);
    testsPassed++;
  } catch (error) {
    console.log(`❌ ${name}: ${error.message}`);
    testsFailed++;
  }
}

function checkFileExists(filePath) {
  return fs.existsSync(filePath);
}

function checkFileContent(filePath, expectedContent) {
  if (!checkFileExists(filePath)) {
    throw new Error(`文件不存在: ${filePath}`);
  }
  const content = fs.readFileSync(filePath, 'utf-8');
  if (!content.includes(expectedContent)) {
    throw new Error(`文件 ${filePath} 缺少预期内容: ${expectedContent}`);
  }
  return true;
}

// 测试文件结构
console.log('📁 1. 项目文件结构测试:');
test('package.json 存在', () => {
  if (!checkFileExists('package.json')) throw new Error('找不到 package.json');
});

test('server.js 存在', () => {
  if (!checkFileExists('server.js')) throw new Error('找不到 server.js');
});

test('public 目录存在', () => {
  if (!checkFileExists('public')) throw new Error('找不到 public 目录');
});

test('public/index.html 存在', () => {
  if (!checkFileExists('public/index.html')) throw new Error('找不到 public/index.html');
});

test('public/game.js 存在', () => {
  if (!checkFileExists('public/game.js')) throw new Error('找不到 public/game.js');
});

// 测试 package.json 内容
console.log('\n📋 2. 项目配置测试:');
test('package.json 包含 express 依赖', () => {
  checkFileContent('package.json', 'express');
});

test('package.json 有正确的启动脚本', () => {
  checkFileContent('package.json', 'node server.js');
});

// 测试 server.js 内容
console.log('\n🚀 3. 服务器代码测试:');
test('server.js 包含 Express 设置', () => {
  checkFileContent('server.js', 'express()');
});

test('server.js 配置了静态文件目录', () => {
  checkFileContent('server.js', 'express.static');
});

test('server.js 监听端口 3000', () => {
  checkFileContent('server.js', 'PORT = 3000');
});

// 测试游戏前端文件
console.log('\n🎮 4. 游戏文件测试:');
test('index.html 包含 Canvas 元素', () => {
  checkFileContent('public/index.html', 'gameCanvas');
});

test('index.html 包含游戏结束界面', () => {
  checkFileContent('public/index.html', 'gameOver');
});

test('game.js 包含蛇的定义', () => {
  checkFileContent('public/game.js', 'snake =');
});

test('game.js 包含食物生成逻辑', () => {
  checkFileContent('public/game.js', 'generateFood');
});

test('game.js 包含碰撞检测', () => {
  checkFileContent('public/game.js', 'endGame');
});

// 测试服务器连接
console.log('\n🌐 5. 服务器连接测试:');

function testServerConnection() {
  return new Promise((resolve) => {
    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/',
      method: 'GET'
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        if (res.statusCode === 200 && data.includes('贪吃蛇游戏')) {
          console.log('✅ 服务器响应正常');
          testsPassed++;
        } else {
          console.log('❌ 服务器响应异常');
          testsFailed++;
        }
        resolve();
      });
    });

    req.on('error', (error) => {
      console.log(`❌ 无法连接到服务器: ${error.message}`);
      testsFailed++;
      resolve();
    });

    req.setTimeout(3000, () => {
      req.destroy();
      console.log('❌ 服务器连接超时');
      testsFailed++;
      resolve();
    });

    req.end();
  });
}

// 测试游戏 JavaScript 文件访问
function testGameJsAccess() {
  return new Promise((resolve) => {
    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/game.js',
      method: 'GET'
    };

    const req = http.request(options, (res) => {
      if (res.statusCode === 200) {
        console.log('✅ game.js 文件可访问');
        testsPassed++;
      } else {
        console.log('❌ game.js 文件访问失败');
        testsFailed++;
      }
      resolve();
    });

    req.on('error', (error) => {
      console.log(`❌ game.js 连接错误: ${error.message}`);
      testsFailed++;
      resolve();
    });

    req.setTimeout(3000, () => {
      req.destroy();
      console.log('❌ game.js 访问超时');
      testsFailed++;
      resolve();
    });

    req.end();
  });
}

async function runServerTests() {
  await testServerConnection();
  await testGameJsAccess();

  console.log('\n📊 测试结果汇总:');
  console.log(`   ✅ 通过: ${testsPassed}`);
  console.log(`   ❌ 失败: ${testsFailed}`);

  if (testsFailed === 0) {
    console.log('\n🎉 所有测试通过！项目运行正常！');
  } else {
    console.log('\n⚠️  部分测试失败，请检查项目配置。');
  }
}

// 运行服务器相关测试
setTimeout(runServerTests, 1000);
"}

